class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._member_set = set(members)
        self._balances = {member: 0.0 for member in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be positive.")

        if payer not in self._member_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            split_among = self.members
        else:
            if not participants:
                raise ValueError("Participants list cannot be empty.")
            for p in participants:
                if p not in self._member_set:
                    raise ValueError(f"Participant '{p}' is not a group member.")
            split_among = participants

        split_amount = amount / len(split_among)
        self._balances[payer] += amount
        for p in split_among:
            self._balances[p] -= split_amount

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return dict(self._balances)

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Separate debtors and creditors
        # Amounts below 1.00 are written off as per requirement 3.
        debtors: list[list] = []
        creditors: list[list] = []

        for member, bal in self._balances.items():
            if bal <= -1.00:
                debtors.append([member, -bal])
            elif bal >= 1.00:
                creditors.append([member, bal])

        payments: list[tuple[str, str, float]] = []
        i = 0
        j = 0

        while i < len(debtors) and j < len(creditors):
            debtor, debt_amt = debtors[i]
            creditor, cred_amt = creditors[j]

            transfer = min(debt_amt, cred_amt)

            # Only propose payments of at least 1.00
            if round(transfer, 2) >= 1.00:
                payments.append((debtor, creditor, round(transfer, 2)))

            debtors[i][1] -= transfer
            creditors[j][1] -= transfer

            # Move pointers when balances are settled or negligibly small
            if debtors[i][1] < 1.00:
                i += 1
            if creditors[j][1] < 1.00:
                j += 1

        return payments
